	private static final String PACKAGE = "org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.";

	@Test
	void sequentialParallelAndRescanCompositionObeyDeclaredLaws() {
		Class<?> registryType = requiredType(PACKAGE + "PackedCostDimensionRegistry");
		Class<?> arenaType = requiredType(PACKAGE + "PackedCostVectorArena");
		Class<?> algebraType = requiredType(PACKAGE + "PackedCostAlgebra");
		Class<?> modeType = requiredType(PACKAGE + "PackedCostAlgebra$CompositionMode");
		Object arena = construct(arenaType);
		Object algebra = construct(algebraType, new Class<?>[] { arenaType }, arena);

		int cpu = dimension(registryType, "steady-state-cpu-work");
		int finalLatency = dimension(registryType, "final-result-latency-ns");
		int peakMemory = dimension(registryType, "peak-memory-bytes");
		assertThat(cpu).isPositive();
		assertThat(finalLatency).isPositive();
		assertThat(peakMemory).isPositive();
		assertThat(dimension(registryType, "output-rows"))
				.as("semantic cardinality is estimator state, not a physical cost dimension")
				.isZero();

		int local = vector(arena, true,
				new int[] { cpu, finalLatency, peakMemory },
				new double[] { 1.0d, 2.0d, 5.0d },
				new double[] { 2.0d, 2.0d, 5.0d },
				new double[] { 3.0d, 2.0d, 5.0d },
				new int[] { 7, 0, 0 });
		int childOne = vector(arena, true,
				new int[] { cpu, finalLatency, peakMemory },
				new double[] { 4.0d, 7.0d, 11.0d },
				new double[] { 5.0d, 7.0d, 11.0d },
				new double[] { 6.0d, 7.0d, 11.0d },
				new int[] { 7, 0, 0 });
		int childTwo = vector(arena, true,
				new int[] { cpu, finalLatency, peakMemory },
				new double[] { 2.0d, 3.0d, 13.0d },
				new double[] { 2.0d, 3.0d, 13.0d },
				new double[] { 2.0d, 3.0d, 13.0d },
				new int[] { 0, 0, 0 });

		int sequential = compose(algebra, modeType, "SEQUENTIAL_SUM", local,
				new int[] { childOne, childTwo }, 1L);
		assertInterval(arena, sequential, cpu, 7.0d, 9.0d, 11.0d, 7);
		assertInterval(arena, sequential, finalLatency, 12.0d, 12.0d, 12.0d, 0);
		assertInterval(arena, sequential, peakMemory, 13.0d, 13.0d, 13.0d, 0);

		int groupedChildren = compose(algebra, modeType, "SEQUENTIAL_SUM", childOne,
				new int[] { childTwo }, 1L);
		int regrouped = compose(algebra, modeType, "SEQUENTIAL_SUM", local,
				new int[] { groupedChildren }, 1L);
		assertThat(invokeLong(arena, "digest", sequential))
				.as("sequential composition is associative")
				.isEqualTo(invokeLong(arena, "digest", regrouped));

		int parallel = compose(algebra, modeType, "PARALLEL_MAX", local,
				new int[] { childOne, childTwo }, 1L);
		assertInterval(arena, parallel, cpu, 7.0d, 9.0d, 11.0d, 7);
		assertInterval(arena, parallel, finalLatency, 9.0d, 9.0d, 9.0d, 0);
		assertInterval(arena, parallel, peakMemory, 29.0d, 29.0d, 29.0d, 0);

		int once = vector(arena, true, new int[] { cpu }, new double[] { 10.0d },
				new double[] { 10.0d }, new double[] { 10.0d }, new int[] { 0 });
		int perOpen = vector(arena, true, new int[] { cpu }, new double[] { 2.0d },
				new double[] { 3.0d }, new double[] { 4.0d }, new int[] { 9 });
		int rescanned = compose(algebra, modeType, "ONCE_PLUS_PER_OPEN", once, new int[] { perOpen }, 4L);
		assertInterval(arena, rescanned, cpu, 18.0d, 22.0d, 26.0d, 9);

		int unknownLatency = vector(arena, false, new int[] { cpu }, new double[] { 1.0d },
				new double[] { 1.0d }, new double[] { 1.0d }, new int[] { 0 });
		int unknownResult = compose(algebra, modeType, "SEQUENTIAL_SUM", unknownLatency,
				new int[] { childOne }, 1L);
		assertThat(invokeBoolean(arena, "isKnown", unknownResult, finalLatency))
				.as("an unknown dimension is never silently treated as zero")
				.isFalse();
	}

	@Test
	void blockingPipelineAndLiveSetCompositionKeepDistinctResourceSemantics() {
		Class<?> registryType = requiredType(PACKAGE + "PackedCostDimensionRegistry");
		Class<?> arenaType = requiredType(PACKAGE + "PackedCostVectorArena");
		Class<?> algebraType = requiredType(PACKAGE + "PackedCostAlgebra");
		Class<?> modeType = requiredType(PACKAGE + "PackedCostAlgebra$CompositionMode");
		Object arena = construct(arenaType);
		Object algebra = construct(algebraType, new Class<?>[] { arenaType }, arena);

		int firstLatency = dimension(registryType, "first-result-latency-ns");
		int finalLatency = dimension(registryType, "final-result-latency-ns");
		int peakMemory = dimension(registryType, "peak-memory-bytes");
		int retainedMemory = dimension(registryType, "retained-memory-bytes");
		int cpu = dimension(registryType, "steady-state-cpu-work");

		int local = vector(arena, true,
				new int[] { firstLatency, finalLatency, peakMemory, retainedMemory, cpu },
				new double[] { 1.0d, 2.0d, 3.0d, 4.0d, 5.0d },
				new double[] { 1.0d, 2.0d, 3.0d, 4.0d, 5.0d },
				new double[] { 1.0d, 2.0d, 3.0d, 4.0d, 5.0d },
				new int[] { 0, 0, 0, 0, 0 });
		int blockingInput = vector(arena, true,
				new int[] { firstLatency, finalLatency, peakMemory, retainedMemory, cpu },
				new double[] { 10.0d, 20.0d, 6.0d, 7.0d, 8.0d },
				new double[] { 10.0d, 20.0d, 6.0d, 7.0d, 8.0d },
				new double[] { 10.0d, 20.0d, 6.0d, 7.0d, 8.0d },
				new int[] { 0, 0, 0, 0, 0 });
		int streamingInput = vector(arena, true,
				new int[] { firstLatency, finalLatency, peakMemory, retainedMemory, cpu },
				new double[] { 7.0d, 11.0d, 8.0d, 9.0d, 10.0d },
				new double[] { 7.0d, 11.0d, 8.0d, 9.0d, 10.0d },
				new double[] { 7.0d, 11.0d, 8.0d, 9.0d, 10.0d },
				new int[] { 0, 0, 0, 0, 0 });

		int blocking = compose(algebra, modeType, "BLOCKING_CHILD", local,
				new int[] { blockingInput, streamingInput }, 1L);
		assertInterval(arena, blocking, firstLatency, 28.0d, 28.0d, 28.0d, 0);
		assertInterval(arena, blocking, finalLatency, 33.0d, 33.0d, 33.0d, 0);
		assertInterval(arena, blocking, peakMemory, 8.0d, 8.0d, 8.0d, 0);

		int pipelined = compose(algebra, modeType, "FIRST_RESULT_PIPELINE", local,
				new int[] { blockingInput, streamingInput }, 1L);
		assertInterval(arena, pipelined, firstLatency, 11.0d, 11.0d, 11.0d, 0);
		assertInterval(arena, pipelined, finalLatency, 22.0d, 22.0d, 22.0d, 0);
		assertInterval(arena, pipelined, peakMemory, 17.0d, 17.0d, 17.0d, 0);

		int liveSet = compose(algebra, modeType, "PEAK_LIVE_SET", local,
				new int[] { blockingInput, streamingInput }, 1L);
		assertInterval(arena, liveSet, peakMemory, 17.0d, 17.0d, 17.0d, 0);
		assertInterval(arena, liveSet, retainedMemory, 20.0d, 20.0d, 20.0d, 0);
		assertInterval(arena, liveSet, cpu, 23.0d, 23.0d, 23.0d, 0);

		int retainedOnce = compose(algebra, modeType, "ONCE_PLUS_PER_OPEN", local,
				new int[] { streamingInput }, 3L);
		assertInterval(arena, retainedOnce, retainedMemory, 13.0d, 13.0d, 13.0d, 0);
		assertInterval(arena, retainedOnce, peakMemory, 8.0d, 8.0d, 8.0d, 0);
		assertInterval(arena, retainedOnce, cpu, 35.0d, 35.0d, 35.0d, 0);
	}

